using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Collections.Concurrent;using System.Security.Cryptography;using System.Security.Principal;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal sealed class ExtLocation {
  internal ExtSource Source;internal ExtVolume Volume;internal string Root;
  internal string Label{get{return "EXT / "+Source.Name+" / "+Volume.Label;}}
  internal ExtRequest Request(string action,string path){return new ExtRequest{Action=action,Source=Source,Volume=Volume,Path=ExtLocations.Relative(path)};}
 }
 internal static class ExtLocations {
  static readonly ConcurrentDictionary<string,ExtLocation> locations=new ConcurrentDictionary<string,ExtLocation>(StringComparer.Ordinal);
  internal static bool IsPath(string path){return path!=null&&path.StartsWith("ext://",StringComparison.Ordinal);}
  internal static string Root(string path){int at=path.IndexOf('/',6);return at<0?path+"/":path.Substring(0,at+1);}
  internal static string Relative(string path){return ExtReader.Normal("/"+path.Substring(Root(path).Length));}
  internal static ExtLocation Get(string path){ExtLocation result;if(!IsPath(path)||!locations.TryGetValue(Root(path),out result))throw new IOException(L.Text("ext.changed"));return result;}
  internal static ExtLocation Register(ExtSource source,ExtVolume volume){if(volume==null||volume.Error!=null)throw new IOException(volume==null?L.Text("ext.noExt"):volume.Error);string key;using(var sha=SHA256.Create())key=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(source.Device+"|"+source.Token+"|"+volume.Offset+"|"+volume.Id))).Replace("-","").Substring(0,24);var location=new ExtLocation{Source=source,Volume=volume,Root="ext://"+key+"/"};locations[location.Root]=location;return location;}
 }
 internal static class ExtDiscovery {
  static int suspended;
  sealed class Suspension:IDisposable {public void Dispose(){lock(gate){suspended--;fingerprint=null;}}}
  internal static async Task<IDisposable> SuspendAsync(){Task previous;lock(gate){suspended++;previous=pending;}var lease=new Suspension();try{if(previous!=null){if(await Task.WhenAny(previous,Task.Delay(6000))!=previous)throw new IOException(L.Text("usb.busy"));try{await previous;}catch{}}return lease;}catch{lease.Dispose();throw;}}
  static readonly object gate=new object();static Task<ExtLocation[]> pending;static DateTime started,scanned;static string fingerprint;static ExtLocation[] cached=new ExtLocation[0];
  internal static bool Elevated{get{return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}}
  internal static Task<ExtLocation[]> Read(){lock(gate){if(suspended>0)return Task.FromResult(cached.Where(x=>!ExtIoGate.IsPaused(x.Source.Device)).ToArray());if(pending==null||(pending.IsCompleted&&DateTime.UtcNow-started>TimeSpan.FromSeconds(8))){started=DateTime.UtcNow;pending=Task.Run(()=>{if(!Elevated)return new ExtLocation[0];var sources=ExtDiskStream.Devices();string stamp=String.Join(";",sources.Select(x=>x.Device+"|"+x.Token+"|"+x.Length).OrderBy(x=>x));if(stamp==fingerprint&&DateTime.UtcNow-scanned<TimeSpan.FromSeconds(60))return cached;scanned=DateTime.UtcNow;var found=new List<ExtLocation>();bool failed=false;foreach(var source in sources){if(ExtIoGate.IsPaused(source.Device))continue;try{var result=ExtReader.Call(new ExtRequest{Action="scan",Source=source},CancellationToken.None);foreach(var volume in result.Volumes.Where(x=>x.Error==null))found.Add(ExtLocations.Register(source,volume));}catch{failed=true;}}cached=found.ToArray();fingerprint=failed?null:stamp;return cached;});}return pending;}}
 }
 public partial class FilePanel {
  internal bool IsExt{get{return ExtLocations.IsPath(CurrentPath);}}
  readonly Dictionary<string,System.Windows.Controls.Button> extDriveButtons=new Dictionary<string,System.Windows.Controls.Button>(StringComparer.Ordinal);
  readonly Dictionary<string,DriveChoice> extChoices=new Dictionary<string,DriveChoice>(StringComparer.Ordinal);bool refreshingExt;
  internal void AddExtChoice(ExtLocation location){if(extChoices.ContainsKey(location.Root))return;var choice=new DriveChoice(location.Root);choice.Update(location.Label,"",false,true,DesktopIcons.DriveBadge(DesktopIcons.StockIcon(8),location.Source.Physical,true));extChoices.Add(location.Root,choice);if(driveButtonsHost!=null){var row=new System.Windows.Controls.StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal};row.Children.Add(new System.Windows.Controls.Image{Source=choice.Icon,Width=driveIconSize,Height=driveIconSize,Margin=new Thickness(0,0,4,0)});row.Children.Add(new System.Windows.Controls.TextBlock{Text="EXT",VerticalAlignment=VerticalAlignment.Center});var button=CompactTheme.Button(row,choice.Tooltip,delegate{SelectDrive(location.Root);});button.Height=driveSelector.Height;button.Padding=driveSelector.Padding;extDriveButtons[location.Root]=button;driveButtonsHost.Children.Insert(Math.Min(driveButtons.Count+extDriveButtons.Count-1,driveButtonsHost.Children.Count),button);}}
  async void RefreshExtChoices(){if(refreshingExt)return;refreshingExt=true;try{var found=await ExtDiscovery.Read();foreach(var location in found)AddExtChoice(location);foreach(var pair in extChoices.ToArray()){var location=ExtLocations.Get(pair.Key);if(location.Source.Physical&&!found.Any(x=>x.Root==pair.Key)){System.Windows.Controls.Button button;if(extDriveButtons.TryGetValue(pair.Key,out button)){driveButtonsHost.Children.Remove(button);extDriveButtons.Remove(pair.Key);}extChoices.Remove(pair.Key);}}if(IsExt){selectingDrive=true;DriveChoice selected;driveSelector.SelectedItem=extChoices.TryGetValue(ExtLocations.Root(CurrentPath),out selected)?selected:null;selectingDrive=false;}}catch(Exception ex){status.ToolTip=ex.Message;}finally{refreshingExt=false;}}
  internal async Task NavigateExt(string path,bool remember){CancelNavigation();int request=navigationVersion;var cancel=new CancellationTokenSource();navigationCancellation=cancel;LocalLoading=true;List.IsEnabled=false;status.Text=L.Text("ext.working");try{var location=ExtLocations.Get(path);var result=await Task.Run(()=>ExtReader.Call(location.Request("list",path),cancel.Token));if(request!=navigationVersion)return;string relative=ExtLocations.Relative(path);var rows=new List<Entry>();if(relative!="/"){string parent=relative.Substring(0,relative.LastIndexOf('/'));rows.Add(new Entry{Name="[..]",IsParent=true,IsDirectory=true,FullPath=location.Root+parent.TrimStart('/'),Icon=DesktopIcons.FileIcon("",true)});}foreach(var item in result.Entries){string extension=item.Directory?"":Path.GetExtension(item.Name);rows.Add(new Entry{Name=item.Directory?"["+item.Name+"]":extension.Length==0?item.Name:item.Name.Substring(0,item.Name.Length-extension.Length),Extension=extension.TrimStart('.'),FullPath=location.Root+item.Path.TrimStart('/'),IsDirectory=item.Directory,Bytes=item.Size,ModifiedTime=item.Modified,Modified=item.DisplayDate,Attributes=item.Readable?"R":item.Kind,Icon=DesktopIcons.FileIcon("file"+extension,item.Directory)});}if(IsArchive)CloseArchiveContext();if(IsRemote){RememberRemote();Remote=null;}if(remember&&CurrentPath!=null&&CurrentPath!=path){history.Push(CurrentPath);forwardHistory.Clear();}CurrentPath=path;AddExtChoice(location);List.ItemsSource=rows;Sort();List.SelectedIndex=rows.Count>0?0:-1;ShowPath();capacity.Text=location.Label+" / "+L.Text("ext.readOnly");capacity.ToolTip=capacity.Text;UpdateDriveSelection();UpdateStatus();if(PathChanged!=null)PathChanged(this,EventArgs.Empty);}catch(OperationCanceledException){}catch(Exception ex){if(request==navigationVersion){status.Text=ex.Message;status.ToolTip=ex.Message;MessageBox.Show(Window.GetWindow(this),ex.Message,L.Text("ext.title"));}}finally{if(request==navigationVersion){LocalLoading=false;List.IsEnabled=true;navigationCancellation=null;if(IsActivePanel)FocusFiles();}cancel.Dispose();}}
  internal Task ExportExt(string[] paths,string target,CancellationToken token){var location=ExtLocations.Get(CurrentPath);var request=location.Request("export",CurrentPath);request.Paths=paths.Select(ExtLocations.Relative).ToArray();request.Target=target;return Task.Run(()=>{var result=ExtReader.Call(request,token);if(result.Skipped>0)throw new IOException(L.Format("ext.exported",result.Completed,result.Skipped,target)+Environment.NewLine+String.Join(Environment.NewLine,result.Warnings??new string[0]));});}
 }
 internal sealed partial class QuickPreviewPane {
  internal void ShowExtFile(string path){var location=ExtLocations.Get(path);LoadingTask=LoadPreparedPreview(path,location.Label+" / "+ExtLocations.Relative(path),L.Text("preview.extractingTemporary"),(temp,token)=>{string name=Path.GetFileName(path);ExtReader.WindowsName(name);var request=location.Request("preview",path);request.Target=Path.Combine(temp.Path,name);ExtReader.Call(request,token);return request.Target;},tempParent:Path.Combine(AppPaths.ConfigDirectory,"ext-panel-preview"));}
 }
 public partial class MainWindow {
  internal FilePanel ExtOriginPanel{get{return active;}}
  internal bool ExtOriginIsRight(FilePanel panel){return panel==right;}
  internal void OpenExtVolume(ExtSource source,ExtVolume volume,bool toRight){if(panelLayout=="Single")SetPanelLayout(lastDualLayout);CloseQuickPreview();var panel=toRight?right:left;var location=ExtLocations.Register(source,volume);panel.AddExtChoice(location);SetActive(panel);panel.Navigate(location.Root,true);}
  async void ExportExtToOther(bool move){var source=active;var target=active==left?right:left;if(move||target.IsRemote||target.IsArchive||target.IsVirtualBrowser||target.CurrentPath==null){MessageBox.Show(this,L.Text("ext.readOnly"),L.Text("ext.title"));return;}var paths=source.Selected().Where(x=>!x.IsParent).Select(x=>x.FullPath).ToArray();if(paths.Length==0)return;string destination=Path.Combine(target.CurrentPath,"Linux-export-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));fileToolsRunning++;try{await source.ExportExt(paths,destination,CancellationToken.None);target.Refresh();}catch(Exception ex){MessageBox.Show(this,ex.Message,L.Text("ext.title"));}finally{fileToolsRunning--;}}
  bool RejectExtWrite(){if(!active.IsExt)return false;MessageBox.Show(this,L.Text("ext.readOnly"),L.Text("ext.title"));return true;}
 }
}
